class Solution {
    public int[][] indexPairs(String text, String[] words) {
        Set<String> s = new HashSet<>(Arrays.asList(words));
        int n = text.length();
        List<int[]> ans = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
